const information=[
 {id:'byd-report',company:'a',type:'announcement',source:'公司公告 · 演示',published:'2026-09-30 08:30',observed:'2026-09-30 08:40',occurred:'报告期截至2026-06-30（仅日期）',event:'财务资料更新',title:'比亚迪：半年报中的现金流怎么看？（演示）',summary:'把利润和经营现金流放在一起看，判断利润是否有现金支持。',judgment:'财务资料已整理，供评分参考',paragraphs:['本地演示半年报用于展示资料阅读和指标出处，不是比亚迪真实公告。报告期截至2026年6月30日；演示发布时间为9月30日。','演示指标：净资产收益率12.0%，近三年经营现金流与净利润合计之比0.96，净债务与EBITDA之比1.20。所有数值均为虚构，不代表公司实际财务表现。','阅读时应结合报告期间、合并范围和指标单位。演示资本配置资料：已披露投资安排，但近期项目回报偏低，后续融资和投入的回报解释仍较薄弱。财务依据与后续经营事件分别记录，避免重复计算同一影响。'],highlight:1},
 {id:'byd-followup',company:'a',type:'news',source:'行业资讯 · 演示',published:'2026-09-29 17:20',observed:'2026-09-29 17:35',occurred:'2026-09-28（仅日期）',event:'订单安排',title:'订单后续：收入仍取决于交付与验收（演示）',summary:'这篇跟进资讯与订单公告讲的是同一件事，可以一起读，但不会算成两次利好。',judgment:'与订单公告归为同一事件',paragraphs:['这是一篇虚构的行业跟进报道，关联公司为比亚迪，用来演示同一事件有多份原文。','本篇补充说明：订单按阶段交付，确认收入仍需完成客户验收。报道没有提供全部收入或利润已经实现的依据。','客户可按约定调整交付节奏。公司需要提前安排备货，并承担延期期间的库存与资金占用；最终利润仍受执行成本影响。'],highlight:1},
 {id:'byd-order',company:'a',type:'announcement',source:'公司公告 · 演示',published:'2026-09-29 15:55',observed:'2026-09-29 16:40',occurred:'2026-09-28（仅日期）',event:'订单安排',title:'比亚迪：订单交付与验收安排（演示）',summary:'订单增加了业务机会，但执行条件仍需要关注，不能直接等同于利润增长。',judgment:'系统已判断，可由研究员修改',paragraphs:['以下订单安排完全虚构，仅借比亚迪名称帮助理解页面，不代表公司的真实经营消息。','订单以分期执行和客户验收为条件，尚不能确认全部转化为利润。客户可以调整交付计划，公司需先行备货，延期可能增加库存和资金占用成本。','公司表示，该订单增加了业务机会；收入将在交付并验收后按实际进度确认，最终回报还取决于执行成本。'],highlight:1},
 {id:'gree-report',company:'b',type:'announcement',source:'公司公告 · 演示',published:'2026-09-28 18:00',observed:'2026-09-28 18:10',occurred:'报告期截至2026-06-30（仅日期）',event:'财务资料更新',title:'格力电器：半年经营与现金流摘要（演示）',summary:'结合盈利、现金流和资本配置阅读财报，再查看A股估值与入选条件。',judgment:'资料已整理，尚无单独事件影响判断',paragraphs:['这是一份本地虚构财务资料，使用格力电器名称说明研究流程，不是公司真实公告。','演示财务指标为：净资产收益率12.0%，近三年经营现金流与净利润合计之比0.96，净债务与EBITDA之比1.20。指标均为固定演示数值。','报告中的财务指标采用同一合并范围，现金流和净利润按三年合计比较；管理层说明了投入计划及资金安排。'],highlight:1}
];
const riskEvidence={id:'risk-example',company:null,type:'announcement',source:'虚构监管材料 · 演示',published:'2026-09-30 10:00',observed:'2026-09-30 10:10',occurred:'2026-09-30 09:00',event:'挂牌风险演练',title:'虚构公司：仅H股挂牌退市决定（演练）',summary:'独立虚构案例，不对应真实公司。',judgment:'仅影响虚构H股挂牌',paragraphs:['这是一份完全虚构的监管材料，演示公司和SYN-H证券均非真实对象。','决定仅指向虚构SYN-H主要挂牌，没有指向同公司A股证券。风险只影响这一挂牌；解除此风险不自动解除另一条公司级风险。','本案例与比亚迪、格力电器无关，仅用于保留风险作用范围与人工修正的设计检查。'],highlight:1};
const evidenceLink=(id,label)=>`<a href="#evidence/${id}" data-action="open-evidence-${id}">${label}</a>`;
const articleOrder=(items)=>[...items].sort((a,b)=>b.published.localeCompare(a.published)||a.id.localeCompare(b.id));
const pendingResearch=(id)=>id==='a'&&(state.judgmentStatus==='waiting'||state.scenario==='missing');
const scoreLink=(id,label='为什么得到这个分数')=>`<a href="#company/${id}" data-action="show-scores">${label}</a>`;
const decisionLink=(label='查看判断与依据')=>`<a href="#decisions/a" data-action="open-impact">${label}</a>`;
function orderJudgment(){
 const r=state.decisionRecords.impact;const value=Number(r.value);const released=r.status==='released';
 return `<div class="judgment-summary"><strong>${released?'等待新的有效判断':(r.status==='auto'?'系统判断：':'人工判断：')+(value>0?'对盈利偏正面':value<0?'对盈利偏负面':'暂不计方向性影响')}</strong><p>${released?'原人工判断已解除，等待按当前资料重新判断。':r.status==='auto'?'订单增加业务机会，但收入需交付验收；执行成本仍需关注。':esc(r.reason||'研究员已按原文修正判断。')}</p><small>${released?'':`影响值${esc(r.value)} · ${r.status==='auto'?'系统已生效':r.status==='waiting'?'判断已保存，评分更新中':'人工已生效'}。正数偏正面，负数偏负面；不是经营总分直接加减的点数。`}</small></div>`;
}
function securityConclusion(security){
 if(pendingResearch(security.id==='b-a'?'b':'a'))return {label:'判断已修改，等待评估',reason:'旧分数只供回看，新经营分和证券结果尚未生成。',date:'更新等待中',tone:'amber'};
 if(security.id==='a-a')return {label:'今日缺价，待评估',reason:'09-30正式收盘价尚未取得，今天不能确认是否继续符合规则。',date:'上次确认09-29：已入选',tone:'amber'};
 if(security.id==='a-h')return {label:'暂未入选',reason:'估值分45.0，未达到当前规则60分要求。',date:'最近评估09-29',tone:'gray'};
 return {label:'已符合1天，还需1天',reason:'最近评估符合规则，还需下一个交易日继续符合才入选。',date:'最近评估09-29',tone:'blue'};
}
function securityCard(sec){const d=securityConclusion(sec);return `<div class="security-card" data-security-id="${sec.id}"><div class="toolbar"><strong>${sec.market} ${sec.name}</strong>${badge(d.label,d.tone)}</div><p>${d.reason}</p><small>${d.date}</small><div class="actions">${sec.id==='a-a'?link('change/missing','查看缺价说明'):sec.id==='a-h'?btn('查看估值依据','open-valuation-'+sec.id,'text-button'):link('strategy','查看入选规则')}${btn((state.watch.includes(sec.id)?'已关注':'关注')+' '+sec.market+' '+sec.name,'watch-'+sec.id,'text-button')}</div></div>`;}
function researchSummary(id){
 const c=companies[id];return `<section class="research-summary" data-company-summary="${id}"><div><span class="quiet">标准价投规则 · 演示资料截至09-30</span><h2>${pendingResearch(id)?'研究判断已修改，等待新的评分和评估':id==='a'?'经营评分达到要求，A股今天暂时无法评估':'经营评分达到要求，A股还需一个交易日确认'}</h2><p>${pendingResearch(id)?'当前先核对已保存的判断；旧结果不会作为新判断的计算结果。':id==='a'?'订单提供业务机会，收入仍需交付和验收。先查看A股缺价原因，再回到订单依据。':'财务资料可继续阅读。股票最近已符合一次规则，尚未正式入选。'}</p></div><div class="actions">${pendingResearch(id)?decisionLink('查看已保存的判断'):id==='a'?link('change/missing','查看今天的缺价说明'):scoreLink(id,'查看经营评分依据')}${id==='a'?evidenceLink('byd-order','阅读订单原文'):evidenceLink('gree-report','阅读财务原文')}</div></section>`;
}
function newsCard(item){const order=item.event==='订单安排';return `<article class="news-row" data-news-id="${item.id}" data-published="${item.published}"><time class="news-date">${item.published.slice(5,10)}<span>${item.published.slice(11)} 发布</span></time><div class="news-content"><div class="news-meta">${badge(item.type==='news'?'新闻':'公告','gray')}<span>${item.source}</span>${link('company/'+item.company,companies[item.company].name)}</div><h3>${evidenceLink(item.id,item.title)}</h3><p>${item.summary}</p>${order?orderJudgment():`<div class="news-research"><span>用于经营评分；尚无独立事件影响判断</span></div>`}<div class="actions">${order?decisionLink():scoreLink(item.company,'查看经营评分依据')}${evidenceLink(item.id,'阅读原文')}${order?evidenceLink(item.id==='byd-order'?'byd-followup':'byd-order','同一事件的另一篇原文'):''}</div></div></article>`;}
function renderNews(){
 const rows=articleOrder(information.filter(x=>(state.newsCompany==='all'||x.company===state.newsCompany)&&(state.newsType==='all'||x.type===state.newsType)&&(state.newsPeriod==='all'||x.published.startsWith('2026-09-30'))));
 return header('新闻资讯','按发布时间从新到旧查看公告和新闻。点开一条，阅读它自己的原文。')+`<div class="toolbar news-filters"><div class="filters"><label for="news-company">公司 <select id="news-company"><option value="all">全部公司</option><option value="a">比亚迪</option><option value="b">格力电器</option></select></label><label for="news-type">类型 <select id="news-type"><option value="all">全部类型</option><option value="announcement">公告</option><option value="news">新闻</option></select></label><label for="news-period">发布时间 <select id="news-period"><option value="all">全部演示日期</option><option value="today">9月30日</option></select></label></div><span class="quiet">${rows.length}篇资讯 · 北京时间</span></div><section class="panel news-feed">${rows.map(newsCard).join('')||`<div class="empty"><h2>没有符合条件的资讯</h2><p>可以切换公司、类型或日期。</p>${btn('清除资讯筛选','clear-news','primary')}</div>`}</section><p class="footnote">新闻按发布时间排列；事件发生时间和系统取得时间在原文页分别列出。同一事件的多篇资讯保留各自原文，评分时只计算一次事件影响。</p>`;
}
const changes=[{id:'enter',type:'ENTER',label:'新入选',tone:'green',company:'a',security:'002594',market:'a',date:'09-29',title:'连续两个交易日收盘后都符合入选条件',body:'经营分72.0，估值分68.0，可以查看当时的规则与原文。'}, {id:'risk',type:'RISK',label:'风险演练',tone:'red',company:null,displayCompany:'虚构公司 · 风险演练',security:'SYN-H（虚构）',market:'h',date:'09-30',title:'仅一只H股挂牌受到退市风险影响（虚构案例）',body:'用于演示风险范围，不涉及比亚迪或格力电器。'}, {id:'missing',type:'MISSING',label:'资料缺口',tone:'amber',company:'a',security:'002594',market:'a',date:'09-30',title:'本交易日最终收盘价尚未取得',body:'当前待评估，保留最后已确认的区间内状态。'}, {id:'config',type:'CONFIG_CHANGE',label:'规则变更',tone:'blue',company:'b',security:'000651',market:'a',date:'09-28',title:'新策略版本建立基线',body:'配置变化单独记录，不作为市场进入或退出。'}];
const can=(cap)=>roles[state.role]?.includes(cap);
const isPhone=()=>window.matchMedia('(max-width:750px)').matches;
const navs={business:[['changes','◷','今日研究'],['news','≡','新闻资讯'],['companies','▤','公司研究'],['strategy','◇','策略候选'],['watchlist','☆','我的自选']],admin:[['sources','▥','数据源'],['jobs','≋','运行任务'],['quality','△','数据质量'],['identity','▦','公司与证券'],['decisions','◎','分析复核'],['templates','▧','评分模板'],['strategy','◇','策略发布'],['models','◈','模型与费用'],['roles','♙','用户与权限'],['audit','≡','审计']]};
const routes={changes:renderChanges,change:renderChange,companies:renderCompanies,company:renderCompany,news:renderNews,evidence:renderEvidence,decisions:renderDecision,templates:renderTemplates,strategy:renderStrategy,watchlist:renderWatchlist,sources:renderSources,jobs:renderJobs,quality:renderQuality,identity:renderIdentity,models:renderModels,roles:renderRoles,audit:renderAudit};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3000);}
function dialog(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal();}
function navigate(route){if(location.hash==='#'+route)render();else location.hash=route;}
function permission(title,body){return `<div class="panel empty"><h2>${title}</h2><p>${body}</p>${link('changes','回到今日研究')}</div>`;}
function currentRoute(){return (location.hash.slice(1)||'changes').split('/');}
function render(){
 const [route,arg]=currentRoute(); if(arg && ['company','decisions'].includes(route))state.company=arg==='b'?'b':'a';
 document.body.dataset.mode=state.mode;
 $('#nav').innerHTML=navs[state.mode].map(([path,icon,name])=>`<a class="nav-link ${route===path||(path==='companies'&&route==='company')||(path==='news'&&route==='evidence')?'active':''}" href="#${path}"><span class="nav-icon" aria-hidden="true">${icon}</span>${name}</a>`).join('');
 $('#business-mode').classList.toggle('selected',state.mode==='business');$('#admin-mode').classList.toggle('selected',state.mode==='admin');$('#role').value=state.role;
 const business=['changes','change','companies','company','news','evidence','watchlist','decisions','templates','strategy','identity'];
 let html=business.includes(route)&&!can('research.read')?permission('此身份没有研究资料查看权限','系统管理员可管理用户和连接，不隐式获得研究判断或策略发布权限。可从上方切换合成身份查看另一条用户路径。'):(routes[route]||renderChanges)(arg);
 const scenario=state.scenario;
 if(scenario==='loading')html=header('正在取得研究快照','保留页面结构，等待资料加载。')+panel('研究资料','<div class="skeleton"></div><div class="skeleton large"></div>'+btn('完成合成加载','finish-load'));
 else if(scenario==='empty')html=header('没有符合条件的结果','当前筛选范围没有可展示的记录。')+`<div class="panel empty"><h2>试试扩大筛选范围</h2><p>这里表示筛选无结果。尚未接入、资料不可见和确实没有变化是不同状态。</p>${btn('清除筛选','finish-load','primary')}</div>`;
 else if(scenario==='permission')html=permission('当前对象不可查看','可见范围已变化，页面不显示原文、分数或计数。请联系本组织管理员检查授权。');
 else if(scenario==='partial')html=notice('部分资料取得失败','比亚迪的原文和经营分仍可查看；本日A股估值缺价，无法作新的入选判断。'+link('quality','查看受影响范围'))+html;
 if(scenario==='updated')html=notice('有新的研究结果','你正在看的快照继续保留。查看新结果后再更新页面，不突然替换正在阅读的内容。','info')+btn('查看新快照','finish-load')+html;
 if(scenario==='suspended')html=notice('证券已停牌','002594 显示暂停并保留上次已确认状态；恢复后需重新确认，不产生重复进入记录。')+html;
 $('#main').innerHTML=html+`<div class="demo-controls"><strong>设计状态演示</strong><label for="scenario">页面状态</label><select id="scenario"><option value="normal">正常</option><option value="loading">加载</option><option value="empty">筛选无结果</option><option value="partial">部分失败</option><option value="permission">不可见</option><option value="conflict">编辑冲突</option><option value="missing">资料不足 / 等待更新</option><option value="updated">新版本提示</option><option value="suspended">停牌</option></select><span>原型状态用于讨论交互，不代表服务端验收。</span></div>`;
 $('#main').dataset.route=location.hash||'#changes';
 $('#scenario').value=state.scenario; $('#scenario').addEventListener('change',e=>{state.scenario=e.target.value;render();});
 bindForms();
}
function renderChanges(){
 const rows=changes.filter(c=>(state.market==='all'||c.market===state.market)&&(state.changeType==='all'||c.type===state.changeType));
 return header('今日研究','持续整理关注公司的资料，检查经营情况和股票是否符合你的筛选规则。')+researchSummary('a')+`<div class="flow-link">${link('company/a','继续研究比亚迪')}${link('news','浏览新闻资讯')}${link('strategy','查看股票是否符合规则')}</div>`+panel('另一家关注公司',`<h3>格力电器 · 000651</h3><p>最近已符合1个交易日，还需下一个交易日继续符合；尚未正式入选。</p>${link('company/b','阅读公司资料')}`)+`<div class="toolbar"><div><h2>演示期间的变化记录</h2><p class="quiet">09-28 至 09-30；以下回答“当时为什么”，不代替当前结论。</p></div><div class="filters">${['all','a','h'].map((x,i)=>btn(['全部市场','A 股','港股'][i],'market-'+x,'filter-button '+(state.market===x?'active':''))).join('')}<label>变化类型 <select id="change-filter"><option value="all">全部变化</option><option value="ENTER">新入选</option><option value="RISK">虚构风险演练</option><option value="MISSING">资料缺口</option><option value="CONFIG_CHANGE">规则变更</option></select></label></div></div><section class="panel">${rows.map(c=>`<article class="change-row"><div class="date">${c.date}<br>当时记录</div><div>${badge(c.label,c.tone)}<h3 style="margin-top:8px">${c.displayCompany||companies[c.company].name}</h3><p>${c.security}</p></div><div><h3>${c.title}</h3><p>${c.body}</p></div>${link('change/'+c.id,'查看当时依据')}</article>`).join('')||'<div class="empty">当前筛选没有记录。</div>'}</section>`;
}
function renderChange(id='enter'){
 const c=changes.find(x=>x.id===id)||changes[0];const isRisk=c.type==='RISK';const missing=c.type==='MISSING';
 return `<div class="breadcrumb">${link('changes','今日研究')} / 固定历史解释</div>`+header(c.title,`${c.displayCompany||companies[c.company].name}　${c.security}　记录日期 2026-${c.date}`,badge(c.label,c.tone))+notice('你正在看当时记录',isRisk?'本条只针对虚构SYN-H挂牌，与真实公司无关。拒绝此风险不会解除另一条公司级风险。':missing?'当日最终收盘价缺失，显示待评估，最后确认状态仍是区间内。':'当时规则和输入已经固定；后续模板、判断和价格变化不会改写本条解释。','info')+`<div class="split">${panel('当时为什么发生变化',`<dl class="definition"><dt>策略发布</dt><dd>标准价投候选 · 发布 1</dd><dt>证券范围</dt><dd>${c.security}，${isRisk?'只适用H挂牌':'按本证券市场独立评估'}</dd><dt>前后状态</dt><dd>${c.type==='CONFIG_CHANGE'?'按新规则建立初始记录':isRisk?'区间外 → 区间外，新增风险原因':missing?'区间内 → 待评估，保留已确认区间内':'区间外 → 区间内'}</dd><dt>经营分 / 覆盖</dt><dd>${isRisk?'不适用':companies[c.company].quality+' / 100%'}</dd><dt>估值分</dt><dd>${isRisk?'45.0':missing?'无有效资料':c.company==='b'?'64.0':'68.0'}</dd><dt>依据</dt><dd>${evidenceLink(isRisk?'risk-example':c.company==='b'?'gree-report':'byd-order','查看对应原文')}</dd></dl>${c.type==='ENTER'?'<ul class="reason-list"><li>公司经营分 72.0 ≥ 70<span>覆盖度100%，必需维度有效</span></li><li>本证券估值分 68.0 ≥ 60<span>A股价格与同口径财务匹配，不使用H股价格</span></li><li>连续两个交易日的正式收盘评估都满足<span>09-28、09-29；不是两次页面刷新</span></li></ul>':''}`)}${panel('查看当前与更正',`<p>历史解释回答“当时为什么”；公司档案回答“现在是什么”。</p><div class="actions">${isRisk?btn('打开虚构风险演练判断','risk-detail'):link('company/'+c.company,'查看当前公司状态')}${link('quality','查看更正与资料缺口')}</div><div class="focus-note">${isRisk?'H挂牌退市不等于公司全部证券退市。':'后来修正s2的输入，也需要检查s4、s6后续依据，不直接改今天的状态。'}</div>`,'固定解释与当前状态分开')}</div>`;
}
function renderCompanies(){
 const list=Object.entries(companies).filter(([,c])=>!state.query||c.name.includes(state.query)||c.securities.some(s=>s.name.toLowerCase().includes(state.query.toLowerCase())));
 return header('公司研究','先找到公司，再查看它的新闻、经营情况和各市场股票的估值。')+`<div class="toolbar"><label class="filters">查找 <input id="company-search" type="search" aria-label="查找公司" placeholder="例如：比亚迪 / 002594" value="${esc(state.query)}"></label><span class="quiet">两家真实公司名 · 三只证券的演示研究</span></div><section class="panel table-wrap"><table><thead><tr><th>公司 / 行业</th><th>经营分</th><th>覆盖度</th><th>证券与状态</th><th>最近变化</th><th>研究</th></tr></thead><tbody>${list.map(([id,c])=>`<tr><td>${link('company/'+id,c.name)}<p>${c.sector}</p></td><td class="number">${pendingResearch(id)?'更新中；旧值'+c.quality:c.quality}<small>09-29${pendingResearch(id)?'历史值':''}</small></td><td>${c.coverage}</td><td>${c.securities.map(s=>`${s.name} ${badge(securityConclusion(s).label,securityConclusion(s).tone)}`).join('<br>')}</td><td>${id==='a'?'财务资料更新，A股报价待补':'已符合1天，还需1天'}</td><td>${link('company/'+id,'打开档案')}</td></tr>`).join('')||'<tr><td colspan="6">没有匹配公司，请修改搜索词。</td></tr>'}</tbody></table></section>`;
}
function renderCompany(id='a'){
 const c=companies[state.company];const missing=pendingResearch(state.company);const tabs=['timeline','events','scores','finance','valuation','relations','notes'];const names=['新闻资讯','研究事件','评分解释','财务','证券估值','关系','笔记'];let body='';
 if(state.tab==='timeline')body=panel('新闻与公告',articleOrder(information.filter(x=>x.company===state.company)).map(newsCard).join(''),'先看系统怎样理解，再沿原文核对依据',link('news','查看全部资讯'));
 else if(state.tab==='events')body=panel('研究事件',state.company==='a'?`<div class="timeline-row"><div class="time-label">09-28<br>发生日期</div><div><h3>订单交付与验收安排（演示）</h3><p>2篇原文讲同一件事，经营影响只计算一次。</p>${orderJudgment()}<div class="actions">${decisionLink()}${evidenceLink('byd-order','订单公告')}${evidenceLink('byd-followup','后续报道')}</div></div></div><div class="timeline-row"><div class="time-label">06-30<br>报告期末</div><div><h3>财务资料更新（演示）</h3><p>用于经营评分，尚无独立事件影响判断。</p>${evidenceLink('byd-report','查看财务原文')}</div></div>`:`<div class="timeline-row"><div class="time-label">06-30<br>报告期末</div><div><h3>财务资料更新（演示）</h3><p>用于经营评分，尚无独立事件影响判断。</p>${evidenceLink('gree-report','查看财务原文')}</div></div>`,'这里把多篇资讯归成事件，再说明对公司的影响');
 else if(state.tab==='scores')body=panel('为什么得到这个分数',`<p class="score-explainer">${missing?'新判断的评分还在更新；以下是09-29的旧评分，供回看。':`09-29经营分${c.quality}，达到当前已发布规则的70分要求。`}所需评分资料覆盖100%，表示本次所需资料齐全，不是结论正确率。</p><div class="split"><div>${c.dimensions.map(([dimension,n,v,w])=>`<div class="dimension-row"><span>${n}<small class="quiet"> ${Math.round(Number(w)*100)}%</small></span><div class="bar"><i style="width:${v}%"></i></div><div class="value">${Number(v).toFixed(1)}</div></div>`).join('')}<p class="footnote">当前生效的五项权重如上。不同公司的定制规则可能不同，不能只按总分直接排名。</p></div><div><h3>沿具体评分查看依据</h3><ul class="reason-list"><li>盈利与现金流<span>结合净资产收益率、现金流与利润关系等财务资料</span>${evidenceLink(state.company==='a'?'byd-report':'gree-report','阅读财务原文')}</li>${state.company==='a'?`<li>订单对盈利的影响<span>业务机会与延期备货成本一并考虑</span>${decisionLink()} · ${evidenceLink('byd-order','阅读订单原文')}</li><li>治理与资本配置<span>按已发布标准对照具体证据选择档位</span>${btn('查看资本配置档位','rubric-detail','text-button')}</li>`:''}</ul></div></div><details class="advanced"><summary>进阶：维护评分规则</summary><p>当前分数使用已发布的五维规则；待发布模板草稿不会改变当前分数。</p>${link('templates','查看当前规则与模板草稿')}</details>`,'当前已发布规则 · 评分日期09-29，模板草稿另行维护');
 else if(state.tab==='valuation')body=panel('按证券查看估值',`<div class="tabs">${c.securities.map(sec=>btn(sec.name+' / '+sec.market,'valuation-'+sec.id,'filter-button '+(state.selectedSecurity===sec.id?'active':''))).join('')}</div>${valuation(c.securities.find(sec=>sec.id===state.selectedSecurity)||c.securities[0])}`,'本套规则中分数越高，表示越符合估值条件；不是收益概率');
 else if(state.tab==='finance')body=panel('财务资料',`<div class="table-wrap"><table><thead><tr><th>指标</th><th>演示值</th><th>怎么算</th><th>原文</th></tr></thead><tbody><tr><td>净资产收益率（近12个月）</td><td>12.0%</td><td>普通股归属利润 / 对应净资产</td><td>${evidenceLink(state.company==='b'?'gree-report':'byd-report','查看指标原文')}</td></tr><tr><td>近3年经营现金流 / 净利润</td><td>0.96</td><td>先分别合计三年金额，再求比值</td><td>${evidenceLink(state.company==='b'?'gree-report':'byd-report','查看三年依据')}</td></tr><tr><td>净债务 / EBITDA</td><td>1.20</td><td>同一财务范围与币种</td><td>${evidenceLink(state.company==='b'?'gree-report':'byd-report','查看指标出处')}</td></tr></tbody></table></div>`,'报告期、发布时间与系统取得时间可在原文页分别查看');
 else if(state.tab==='relations')body=panel('公司与股票的关系',`<h3>${c.name}</h3><ul class="reason-list">${c.securities.map(sec=>`<li>${sec.name} / ${sec.market}<span>${sec.currency}报价。公司经营资料共用，各市场股票分别估值。</span></li>`).join('')}</ul><details class="advanced"><summary>进阶：查看身份与挂牌资料</summary>${link('identity','查看公司与证券资料')}</details>`);
 else body=panel('研究笔记',`<form id="notes-form"><div class="form-group"><label for="note">我的私人笔记</label><textarea id="note" placeholder="记录你的研究疑问，默认仅本人可见">${esc(state.note)}</textarea><small>本次演示中保留，刷新页面后清空。</small></div><button type="submit" class="primary">保存笔记</button></form>`);
 return `<div class="breadcrumb">${link('companies','公司研究')} / ${c.name}</div>`+header(`<span class="company-identity"><span class="company-monogram">${c.name.slice(0,1)}</span><span>${c.name}<small>${c.sector} · 演示研究</small></span></span>`,'先看当前结论，再查原文和评分依据。')+researchSummary(state.company)+`<section class="panel current-securities"><div class="panel-head"><h2>各市场股票目前怎样</h2></div><div class="panel-body security-grid">${c.securities.map(securityCard).join('')}</div></section>`+panel('公司经营质量',`<div class="score-overview"><div><div class="score-number">${missing?'—':c.quality}</div><p>${missing?'评分更新中':'经营分 / 100'}</p></div><div><strong>${missing?'新结果待更新':'09-29：达到当前规则70分要求'}</strong><p>${missing?'旧经营分'+c.quality+'（09-29），只供回看':'所需评分资料覆盖'+c.coverage+'，不是结论正确率'}</p>${scoreLink(state.company)}</div></div>`)+`<div class="tabs">${tabs.map((x,i)=>btn(names[i],'tab-'+x,state.tab===x?'active':'')).join('')}</div>${body}`;
}
function valuation(sec){const d=securityConclusion(sec);return `<div class="valuation-current">${badge(d.label,d.tone)}<p>${d.reason}</p><small>${d.date}</small></div><dl class="definition"><dt>证券 / 币种</dt><dd>${sec.name} / ${sec.currency}</dd><dt>估值分</dt><dd><strong style="font-size:30px">${sec.v}</strong>（09-29${sec.id==='a-a'||pendingResearch(sec.id==='b-a'?'b':'a')?'历史值，只供回看':''}）</dd><dt>本策略要求</dt><dd>估值分至少60；还需经营、财务和风险等条件同时符合</dd><dt>所用收盘价</dt><dd>${sec.price} ${sec.currency} · 2026-09-29</dd><dt>财务依据</dt><dd>${evidenceLink(sec.id==='b-a'?'gree-report':'byd-report','查看财务原文')}</dd></dl><p class="footnote">估值分越高，表示越符合本套估值条件，不是股价越贵。行情为固定演示快照。今日缺价或判断更新时，旧分数不表示今天仍符合规则。</p>`;}
function renderEvidence(id='byd-order'){
 const item=id==='risk-example'?riskEvidence:information.find(x=>x.id===id);
 if(!item)return header('未找到这篇原文','请回到资讯列表选择一篇资料。')+link('news','返回新闻资讯');
 const company=item.company;const related=information.filter(x=>x.company===item.company&&x.event===item.event&&x.id!==item.id);
 return `<div class="breadcrumb">${link(state.evidenceReturn,'返回刚才的列表')} / 原文</div>`+header(item.title,'本地完整演示原文。摘要和研究判断都可以回到具体段落核对。')+`<div class="split">${panel('原文',`<div class="document" data-evidence-id="${item.id}"><dl class="document-meta definition"><dt>来源</dt><dd>${item.source}</dd><dt>发布时间</dt><dd>${item.published}（北京时间）</dd><dt>系统取得</dt><dd>${item.observed}（北京时间）</dd><dt>事件发生</dt><dd>${item.occurred}</dd><dt>正文定位</dt><dd>第${item.highlight+1}段 · 本地演示版本1</dd></dl><p class="demo-source-note">这篇原文是虚构演示材料，并非真实新闻或公告。正式接入后，此处提供获许可来源的原文网址。</p>${item.paragraphs.map((t,i)=>`<p id="paragraph-${i+1}"><small class="quiet">${i+1}　</small>${i===item.highlight?'<mark>'+esc(t)+'</mark>':esc(t)}</p>`).join('')}</div>`)}${panel('这篇资料与研究的关系',`<dl class="definition"><dt>关联公司</dt><dd>${company?link('company/'+company,companies[company].name):'虚构公司 · 风险演练'}</dd><dt>研究事件</dt><dd>${item.event}</dd><dt>用途</dt><dd>${item.event==='订单安排'?'判断事件对盈利的影响':'财务与经营评分参考'}</dd></dl>${item.event==='订单安排'?orderJudgment():'<p>用于经营评分，尚无独立事件影响判断。</p>'}${related.length?'<h3>同一事件的其他原文</h3><ul class="reason-list">'+related.map(x=>'<li>'+evidenceLink(x.id,x.title)+'</li>').join('')+'</ul>':''}<div class="actions">${item.id==='risk-example'?btn('查看虚构风险判断','risk-detail'):item.event==='订单安排'?decisionLink():company?link('company/'+company,'继续研究公司'):''}</div>${btn('演示证据不可访问','evidence-revoke','text-button')}`)}</div>`;
}
function renderDecision(){
 state.company='a';
 const kind=state.decisionKind;const impact=kind==='impact';const rubric=kind==='rubric';const risk=kind==='risk';const permitted=can('analysis.override');
 const label=impact?'订单对盈利的影响（演示）':rubric?'资本配置 · 评分档位':'虚构H股挂牌退市风险（演练）';
 const record=state.decisionRecords[kind];const old=record.value;
 const newValue=impact?state.replacement:rubric?state.grade:'拒绝本风险';
 const waiting=record.status==='waiting'||state.scenario==='missing';
 return `<div class="breadcrumb">${link(risk?'change/risk':'company/a',risk?'虚构风险演练':'公司研究')} / 查看和修改判断</div>`+header(label,'查看原文、旧值与完整新值，明确作用对象后直接保存。',badge(record.status==='auto'?'系统判断已生效':record.status==='released'?'覆盖已解除，等待重新评估':'人工判断已生效',record.status==='auto'?'blue':'amber'))+`<div class="tabs">${['impact','rubric','risk'].map((x,i)=>btn(['影响值','评分档位','虚构风险演练'][i],'decision-'+x,kind===x?'active':'')).join('')}</div>`+(state.scenario==='conflict'?notice('判断已被另一位研究员更新','你的新值和理由保留在下方。当前服务器示例值已变化，比较后可基于新版本重试。','error'):'')+(waiting?notice('人工判断已保存，重算等待中','新判断优先于后续系统建议；公司评分和A/H评估尚未完成。'+(risk?'若仍有公司级违约，两只证券继续受风险影响。':''),'info'):'')+`<div class="split">${panel('原文依据',`<p>${risk?'虚构监管决定仅影响一只H股挂牌。':rubric?'以财务资料和资本配置证据对照评分档位。':'订单分期执行，需经客户验收，不能确认全部转化为利润。'}</p><div class="focus-note">${risk?'这条虚构决定只指向SYN-H主要挂牌，与比亚迪及格力电器无关。':rubric?'按评分标准和证据选择档位；资料不够时保留待判断。':'修改影响是修改经营判断，不是预测股价。'}</div>${evidenceLink(risk?'risk-example':rubric?'byd-report':'byd-order','打开完整原文与证据定位')}<dl class="definition"><dt>主体</dt><dd>${risk?'虚构公司 · 风险演练':'比亚迪（演示研究）'}</dd><dt>作用范围</dt><dd>${risk?'仅虚构SYN-H主挂牌':'公司经营评分；A/H共享经营事实，各自估值'}</dd><dt>生效方式</dt><dd>从本次实际知悉时点生效，不回填系统历史</dd><dt>有效期</dt><dd>合成演练至2026-10-31；到期按当时有效资料重新判断</dd><dt>输入证据</dt><dd>${rubric?'财务原文第3段':'本页原文第2段'}</dd></dl>`)}${panel('当前判断与修改',`${impact?orderJudgment():rubric?'<p>按资本配置标准评分。当前档位：'+esc(old)+'</p>':'<p>当前风险只作用于虚构H股挂牌。</p>'}<details id="decision-editor" class="advanced" ${state.editDecision?'open':''}><summary>修改这一判断</summary><div class="value-compare"><div class="value-box"><span>当前有效值</span><strong>${esc(old)}</strong><small>${state.scenario==='conflict'?'冲突：已有更新版本':'当前判断版本 '+record.generation}</small></div><div class="value-box"><span>准备修改为</span><strong>${esc(newValue)}</strong><small>新修订保留旧值与原因</small></div></div>${!permitted?notice('此角色只能查看','查看者、策略管理员与系统管理员没有修改判断权限。可切换研究员身份体验。'):''}<form id="override-form"><div class="form-group"><label for="replacement">${impact?'新影响值（−1 至 +1）':rubric?'新档位（0 至 4）':'明确动作'}</label>${impact?`<input id="replacement" name="replacement" type="number" min="-1" max="1" step="0.1" value="${esc(state.replacement)}" ${!permitted?'disabled':''}>`:rubric?`<select id="grade" ${!permitted?'disabled':''}>${[0,1,2,3,4].map(g=>`<option ${String(g)===state.grade?'selected':''}>${g}</option>`).join('')}</select>`:'<p>拒绝这一条确切挂牌风险；不一并清除公司其他风险。</p>'}<small>${impact?'正数表示正面，负数表示负面，0表示不计方向性影响；影响值不是经营总分直接加减的点数。例：若原文中的延期库存成本使盈利承压，可据此写理由再改值。':rubric?'0：重大配置失误反复且未解释；1：资本回报差、融资/投资逻辑薄弱；2：配置规则明确，结果与解释基本一致；3：回报纪律好，投资/回购/分红与机会匹配；4：跨周期配置结果与纪律持续，失败复盘透明。':'只拒绝这一条风险，其他独立风险仍保留。'}</small></div><div class="form-group"><label for="reason">修改理由</label><textarea id="reason" required placeholder="说明证据为什么支持新判断" ${!permitted?'disabled':''}>${esc(state.reason)}</textarea></div><div id="override-error" class="form-error" role="alert"></div><div class="actions"><button type="submit" class="primary" ${!permitted?'disabled':''}>${risk?'拒绝本风险':'保存人工覆盖'}</button></div></form>${record.status!=='auto'&&record.status!=='released'?`<div class="actions">${btn('查看合成重算结果','show-recompute')}${btn('解除人工覆盖','release-override','text-button',!permitted?'disabled':'')}</div>`:''}<p class="footnote">保存后先更新判断，评分与股票评估随后更新；本页只演示这一过程。</p></details>`,'对照原判断、新判断和原文依据')}</div>`;
}
function renderTemplates(){
 const editable=can('template.edit')&&!isPhone();const publish=can('template.publish')&&!isPhone();
 return header('三层评分模板','先用通用规则，再按行业和公司调整。下方客户留存草稿需要发布后才生效。',badge(state.templatePublished?'演示新版本已发布':'合成企业草稿','blue'))+panel('当前生效规则',`<p>比亚迪09-29的72分使用已发布五维方案：盈利35%、财务韧性20%、商业模式25%、治理15%、成长5%。下方草稿尚未作用于当前结果。</p>${scoreLink('a','阅读当前评分解释')}`,'当前评分与待发布草稿分别查看')+`<h2 class="section-heading">待发布草稿：增加客户留存维度</h2><div class="steps"><div class="step"><strong>通用基础 · v2</strong><span>注册维度、标准口径与权重</span></div><div class="step"><strong>制造业 · v2</strong><span>固定引用基础v2</span></div><div class="step active"><strong>比亚迪 · 企业差异</strong><span>只影响这一家公司的经营评分</span></div></div>${!editable?notice(isPhone()?'手机查看模式':'当前角色仅查看模板',isPhone()?'复杂模板编辑与发布请到桌面完成。':'研究员或策略管理员可编辑；策略管理员才能发布。'):''}<section class="panel"><div class="panel-head"><div><h2>默认规则、公司调整与生效规则</h2><p>除了权重，也可以设置资料要求与有效期。</p></div>${badge('客户留存维度 · 已注册可用','gray')}</div><div class="table-wrap"><table><thead><tr><th>配置项</th><th>继承值</th><th>公司自定义</th><th>最终值与来源</th></tr></thead><tbody><tr><td>盈利质量权重</td><td>基础25% → 制造业30%</td><td>本扩展草稿未覆盖</td><td>30% · 制造业</td></tr><tr><td>治理评分资料有效期</td><td>180日</td><td><label class="visually-hidden" for="template-age">公司资料有效期</label><select id="template-age" ${!editable?'disabled':''}><option ${state.templateAge==='90'?'selected':''}>90</option><option ${state.templateAge==='180'?'selected':''}>180</option></select> 日</td><td>${state.templateAge}日 · 企业；还需满足策略的资料要求</td></tr><tr><td>证据要求</td><td>可访问原文</td><td>发行人 / 监管原文</td><td>发行人 / 监管原文 · 企业</td></tr><tr><td>完整草稿权重</td><td>30 / 20 / 25 / 15 / 10%</td><td>成长5%，客户留存5%</td><td>六维合计100%；当前已发布企业方案盈利35%、成长5%</td></tr><tr><td>客户留存维度</td><td>注册目录已提供，基础模板未启用</td><td>已注册样例；完整基准与权重</td><td>客户留存维度；由人维护注册</td></tr><tr><td>事件是否影响评分</td><td>接受事件</td><td><label class="visually-hidden" for="event-mode">事件是否影响评分方式</label><select id="event-mode" ${!editable?'disabled':''}><option value="enabled" ${state.eventMode==='enabled'?'selected':''}>参与评分 · 影响逐渐减弱（90日）</option><option value="disabled" ${state.eventMode==='disabled'?'selected':''}>只用基础评分</option></select></td><td>${state.eventMode==='enabled'?'可接受受限影响；半衰期90日':'拒绝该维度影响；不额外计算事件影响'}</td></tr></tbody></table></div></section>${notice('资料发布120天后的对照',state.templateAge==='90'?'资料已超过90日有效期：若策略需要这一项，暂时无法评估。已经发布的策略仍使用原来的180日规则。':'资料仍在180日有效期内；还需满足原文权利与其他质量要求。','info')}<div class="actions">${btn('保存草稿','save-template','secondary',!editable?'disabled':'')}${btn('模拟与差异预览','preview-template','primary',!editable?'disabled':'')}${btn('还原继承','restore-template','text-button',!editable?'disabled':'')}</div>${state.templatePreview?panel('固定输入差异预览',`<p>受影响：比亚迪1家公司，002594 / 01211两只证券。格力电器不受企业差异影响。</p><div class="preview-diff">${badge('旧口径：180日','gray')}<span>→</span>${badge('新口径：'+state.templateAge+'日','amber')}</div><p>${state.eventMode==='disabled'?'客户留存只按基准；事件影响不能落入这一维度。':'客户留存允许受限事件影响。'}</p><p class="footnote">仅展示固定场景对照，不运行模板解析/评分引擎。完整维度与权重示例见仓库examples/v03-template-custom.json。</p><div class="actions">${btn('发布新模板版本','publish-template','primary',!publish?'disabled':'')}</div>${!publish?'<p class="footnote">你可编辑与预览，发布由策略管理员完成。</p>':''}`):''}`;
}
function renderStrategy(){
 const allowed=can('strategy.publish')&&!isPhone();
 const rows=Object.values(companies).flatMap(c=>c.securities.map(s=>({c,s})));
 return header('是否符合我的选股规则','先看最近评估的结论和日期。资料不足时，历史入选不代表今天仍符合。',badge(state.strategyPublished?'演示发布 2':'当前规则 · 发布1','blue'))+panel('当前已发布规则',`<p>经营分至少70、资料覆盖至少80%、估值分至少60，还需财务与风险条件同时通过，连续两个交易日确认后入选。</p><p class="quiet">下面维护的是新草稿；修改草稿不会替换当前规则和结果。</p>`)+`<section class="panel table-wrap"><table><thead><tr><th>公司 / 股票</th><th>经营分 / 日期</th><th>估值分 / 日期</th><th>当前结论</th><th>原因与下一步</th></tr></thead><tbody>${rows.map(({c,s:sec})=>{const d=securityConclusion(sec);const id=sec.id==='b-a'?'b':'a';return `<tr data-candidate-id="${sec.id}"><td>${link('company/'+id,c.name)}<p>${sec.name} / ${sec.market}</p></td><td>${pendingResearch(id)?'新评分待更新；旧值'+c.quality:c.quality}<p>09-29${pendingResearch(id)?'历史值':''} · 覆盖100%</p></td><td>${sec.id==='a-a'||pendingResearch(id)?'上次估值分'+sec.v:sec.v}<p>09-29${sec.id==='a-a'||pendingResearch(id)?'历史值':''}</p></td><td>${badge(d.label,d.tone)}<p>${d.date}</p></td><td>${d.reason}<p>${link(sec.id==='a-a'?'change/missing':'company/'+id,sec.id==='a-a'?'查看缺价说明':'查看评分与估值依据')}</p></td></tr>`;}).join('')}</tbody></table></section><details id="strategy-editor" class="advanced strategy-maintenance" ${state.strategyEditing||state.strategyPreview?'open':''}><summary>进阶：调整选股规则、模拟与发布</summary>${panel('维护策略草稿',`<div class="form-grid"><div class="form-group"><label for="strategy-threshold">进入经营分阈值</label><select id="strategy-threshold" ${!allowed?'disabled':''}><option ${state.strategyThreshold==='70'?'selected':''}>70</option><option ${state.strategyThreshold==='75'?'selected':''}>75</option></select><small>退出维持阈值65、其他条件沿用固定样例。只提供有对照快照的两个演示选项。</small></div><div><h3>条件的业务解释</h3><p>经营分 ≥ ${state.strategyThreshold}，覆盖 ≥ 80%，证券估值 ≥ 60；财务指标与风险门保持。</p><p class="footnote">需连续两个交易日确认；中途资料缺失时重新计数。</p></div></div>${!allowed?notice(isPhone()?'手机查看模式':'当前身份没有策略编辑/发布能力',isPhone()?'复杂规则编辑、模拟和发布请到桌面完成。':'研究员可覆盖判断，不能发布策略。切换策略管理员可体验模拟发布。'):''}<div class="actions">${btn('固定时点模拟','simulate-strategy','primary',!allowed?'disabled':'')}</div>`,'草稿改动使旧预览失效，发布不改旧版')}${state.strategyPreview?panel('模拟变化预览',`<div class="steps"><div class="step active"><strong>固定时点</strong><span>2026-09-29收盘输入</span></div><div class="step active"><strong>比较变化</strong><span>${state.strategyThreshold==='75'?'比亚迪72不再满足进入条件':'沿用原进入阈值'}</span></div><div class="step"><strong>发布新基线</strong><span>记录为规则变更</span></div></div><table><thead><tr><th>证券</th><th>旧规则</th><th>新规则基线</th></tr></thead><tbody><tr><td>002594</td><td>区间内</td><td>${state.strategyThreshold==='75'?'区间外 · 规则变更':'区间内 · 原规则符合'}</td></tr><tr><td>01211</td><td>区间外</td><td>区间外 · 估值条件未满足</td></tr><tr><td>000651</td><td>待确认</td><td>新规则先记录当前结果，不算作市场变化引起的新入选</td></tr></tbody></table><p class="footnote">固定样例模拟结果，无实时策略计算；发布只更新原型版本标签。</p><div class="actions">${btn('确认发布新版本','publish-strategy','primary',!allowed?'disabled':'')}</div>`):''}${panel('发布历史与回滚','<p>发布1继续保留固定规则和历史解释。回滚应引用旧配置创建新策略版本并重新预览，不覆盖发布1。</p>'+btn('查看回滚预览','rollback-preview','text-button',!allowed?'disabled':''))}</details>`;
}
function renderWatchlist(){const securities=Object.entries(companies).flatMap(([id,c])=>c.securities.map(s=>({id,c,s}))).filter(x=>state.watch.includes(x.s.id));return header('我的自选','按证券保存，研究时可以回到同一公司档案。')+panel('关注证券',securities.length?`<div class="table-wrap"><table><thead><tr><th>公司 / 证券</th><th>经营分</th><th>证券状态</th><th>操作</th></tr></thead><tbody>${securities.map(({id,c,s})=>`<tr><td>${link('company/'+id,c.name)}<p>${s.name}</p></td><td>${pendingResearch(id)?'更新中；旧值'+c.quality:c.quality}<p>09-29${pendingResearch(id)?'历史值':''}</p></td><td>${badge(securityConclusion(s).label,securityConclusion(s).tone)}<p>${securityConclusion(s).date}</p></td><td>${btn('移出自选','unwatch-'+s.id,'text-button')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h2>开始关注一个研究对象</h2><p>在公司档案关注明确的一只股票。</p>${link('companies','查找公司')}</div>`);}
function adminPermission(cap,title){return !can(cap)?permission('此身份没有'+title+'权限','请切换对应合成角色查看管理交互。管理权限与业务覆盖/发布分别授予。'):null;}
function renderSources(){const denied=adminPermission('source.manage','数据源管理');if(denied)return denied;return header('数据源','先看采集范围、最近成功与业务影响，再展开技术诊断。')+panel('本地合成披露源',`<div class="toolbar"><h3>local-fixture</h3>${badge(state.sourcePaused?'已暂停':'已启用',state.sourcePaused?'amber':'green')}</div><dl class="definition"><dt>业务范围</dt><dd>两家公司，三只证券</dd><dt>权利状态</dt><dd>合成fixture，可读/保存/分析；不配置真实凭证</dd><dt>最近运行</dt><dd>${state.imported?'演示导入完成':'等待演示导入'}</dd><dt>下一计划</dt><dd>${state.sourcePaused?'暂停后不再安排新的采集任务':'固定演练计划，不实际调度'}</dd></dl><div class="actions">${btn(state.imported?'查看导入结果':'导入合成资料','import-fixture','primary',state.sourcePaused?'disabled':'')}${btn(state.sourcePaused?'恢复计划':'暂停计划','toggle-source')}${link('jobs','查看采集任务')}</div>`)+panel('频率与范围说明','<p>真实源适配时再固定供应商、抓取/保存/模型分析/导出权利。配置发布可先预览请求量与回溯范围；常规草稿不逐项审批。</p>'+btn('查看配置发布预览','source-preview','text-button'));}
function renderJobs(){const denied=!(can('job.retry')||can('ops.read'));if(denied)return permission('仅运行管理身份可查看任务','数据管理员可以恢复失败项，系统管理员可以查看运行诊断。');return header('运行任务','失败项与受影响公司一起显示，不把失败冒充没有资料。')+panel('合成行情更新',`<div class="toolbar"><h3>002594 正式收盘价</h3>${badge(state.jobRecovered?'演示恢复完成':'一项失败',state.jobRecovered?'green':'amber')}</div><dl class="definition"><dt>影响</dt><dd>${state.jobRecovered?'已取得固定样例，等待策略重评':'002594 当前待评估，保留最后已确认区间内'}</dd><dt>原因</dt><dd>演示源暂缺当日正式收盘价</dd><dt>恢复范围</dt><dd>只恢复当日失败项，保留历史入选和退出记录</dd><dt>账本</dt><dd>沿用完整逻辑键与cutoff，丢ACK不重复生效</dd></dl><div class="actions">${btn('预览失败项恢复','retry-preview','primary',!can('job.retry')?'disabled':'')}${link('quality','查看业务影响')}${link('company/a','回到公司研究')}</div>`)+panel('导入与分析阶段','<div class="steps"><div class="step active"><strong>原文保存</strong><span>演示成功</span></div><div class="step active"><strong>判断保存</strong><span>自动接受 / 人工覆盖</span></div><div class="step"><strong>评分与评估</strong><span>按同一时点更新评分与策略</span></div></div>');}
function renderQuality(){if(!(can('research.read')||can('ops.read')))return permission('无法查看质量影响','切换研究或运营身份查看合成对象。');return header('数据质量与更正','先确认影响什么业务，再选择恢复资料或纠正历史。')+panel('当前资料缺口',`<div class="toolbar"><div><h3>002594缺少本日最终价</h3><p>今天暂时不能更新策略结果，其他公司资料仍可阅读。</p></div>${badge(state.jobRecovered?'演示已恢复':'待恢复','amber')}</div><div class="actions">${link('jobs','定位失败任务')}${link('change/missing','查看固定缺口解释')}</div>`)+panel('封存历史更正',`<p>合成s2输入错误，后续s4退出、s6进入各有独立依据。更正s2先重放受影响窗口，不直接把今天IN改OUT。</p><div class="steps"><div class="step"><strong>s2 当时进入</strong><span>保留原记录</span></div><div class="step"><strong>s4 后续退出</strong><span>检查是否仍成立</span></div><div class="step active"><strong>s6 独立进入</strong><span>当前IN保留</span></div></div><div class="actions">${btn('查看更正范围预览','correction-preview','secondary',!can('quality.correct')?'disabled':'')}</div>${state.correctionAdded?notice('已追加合成更正说明','当前状态仍IN，演示未删除旧ENTER/EXIT。','info'):''}<p class="footnote">现在新出现的知识从实际知悉时点生效，不借纠错回填历史。</p>`);}
function renderIdentity(){return header('公司与证券身份','主体、证券、挂牌三层分开；合并前先比较范围。')+panel('比亚迪',`<div class="table-wrap"><table><thead><tr><th>经营主体</th><th>工具</th><th>主要挂牌</th><th>币种</th><th>作用范围</th></tr></thead><tbody><tr><td>比亚迪</td><td>002594 / A类</td><td>合成A挂牌</td><td>CNY</td><td>独立估值和策略状态</td></tr><tr><td>同一公司</td><td>01211 / H类</td><td>合成H挂牌</td><td>HKD</td><td>独立估值和策略状态</td></tr></tbody></table></div><div class="actions">${btn('主数据变更影响预览','identity-preview','secondary',!can('identity.manage')?'disabled':'')}</div><p class="footnote">旧主体ID与历史关系不删除，原历史评估继续引用原身份版本。</p>`);}
function renderModels(){const denied=adminPermission('model.configure','模型配置');if(denied)return denied;return header('模型与费用','先用mock模型贯通分析路径，记录用量和失败原因。')+panel('分析适配器',`<dl class="definition"><dt>当前模型</dt><dd>mock-fixture（无网络）</dd><dt>自动审核</dt><dd>固定auto-review-policy与校准引用；没有可用校准不能伪造可信程度</dd><dt>外部模型</dt><dd>目标能力已保留，真实接入另行实施</dd><dt>用量</dt><dd>0次真实请求 / 0实际token / 无采购</dd></dl><p>凭证只在正式受控配置中引用，不出现在本原型或Git。</p>`);}
function renderRoles(){const denied=adminPermission('role.assign','角色管理');if(denied)return denied;return header('用户与角色','五角色可兼任。系统管理能力与业务判断、发布能力分别授予。')+panel('合成研究员：示例成员',`<form id="roles-form"><div class="checkbox-list">${[['viewer','查看者'],['researcher','研究员'],['strategy_manager','策略管理员'],['data_admin','数据管理员'],['system_admin','系统管理员']].map(([v,n])=>`<label><input type="checkbox" name="roles" value="${v}" ${v==='researcher'?'checked':''}>${n}</label>`).join('')}</div><p class="quiet">本例只修改这一名合成成员；不允许无替代撤掉最后管理员。</p>${btn('查看权限差异','role-preview','primary')}</form>`)+`<div class="role-grid">${Object.entries(roles).filter(([x])=>x!=='lead').map(([r,caps])=>`<div class="role-card"><h3>${{viewer:'查看者',researcher:'研究员',strategy_manager:'策略管理员',data_admin:'数据管理员',system_admin:'系统管理员'}[r]}</h3><p>${caps.map(x=>({['research.read']:'研究读取',['analysis.override']:'人工覆盖',['template.edit']:'模板编辑',['template.publish']:'模板发布',['strategy.publish']:'策略发布',['source.manage']:'源管理',['job.retry']:'失败项重试',['quality.correct']:'质量纠错',['identity.manage']:'身份维护',['role.assign']:'角色分配',['model.configure']:'模型配置',['audit.read']:'审计读取',['ops.read']:'运行读取'}[x])).join('、')}</p></div>`).join('')}</div>`;}
function renderAudit(){const denied=adminPermission('audit.read','审计读取');if(denied)return denied;return header('操作记录','动作与对象修订可追溯，不展示凭证或原始私有日志。')+panel('合成演示记录',`<ul class="reason-list"><li>研究员修订影响值<span>旧修订保留；当前判断更新为新版本。</span></li><li>策略管理员发布固定规则<span>预览输入、父链及每家公司解析口径固定。</span></li><li>状态与outbox提交<span>正式实现必须同事务；此处只是设计样例。</span></li></ul>`);}
function bindForms(){
 for(const [id,key] of [['news-company','newsCompany'],['news-type','newsType'],['news-period','newsPeriod']]){const el=$('#'+id);if(el){el.value=state[key];el.onchange=e=>{state[key]=e.target.value;render();};}}
 const f=$('#change-filter');if(f){f.value=state.changeType;f.onchange=e=>{state.changeType=e.target.value;render();};}
 const search=$('#company-search');if(search)search.oninput=e=>{state.query=e.target.value;const p=e.target.selectionStart;render();const n=$('#company-search');n.focus();n.setSelectionRange(p,p);};
 const strategyEditor=$('#strategy-editor');if(strategyEditor)strategyEditor.querySelector('summary').onclick=()=>{state.strategyEditing=!strategyEditor.open;};
 const editor=$('#decision-editor');if(editor)editor.querySelector('summary').onclick=()=>{state.editDecision=!editor.open;};
 const replacement=$('#replacement');if(replacement)replacement.oninput=e=>{state.replacement=e.target.value;};
 const grade=$('#grade');if(grade)grade.onchange=e=>{state.grade=e.target.value;};
 const reason=$('#reason');if(reason)reason.oninput=e=>{state.reason=e.target.value;};
 const form=$('#override-form');if(form)form.onsubmit=e=>{e.preventDefault();if(!can('analysis.override'))return;const err=$('#override-error');if(!state.reason.trim()){err.textContent='请写明修改理由，便于回查证据。';return;}if(state.decisionKind==='impact'&&(state.replacement===''||!Number.isFinite(Number(state.replacement))||Number(state.replacement)<-1||Number(state.replacement)>1)){err.textContent='影响值须为−1至+1之间的数值。';return;}if(state.scenario==='conflict'){err.innerHTML='示例409：你的草稿保留。'+btn('比较并采用新版本重试','resolve-conflict','text-button');return;}const record=state.decisionRecords[state.decisionKind];record.value=state.decisionKind==='impact'?state.replacement:state.decisionKind==='rubric'?state.grade:'人工拒绝本挂牌风险';record.reason=state.reason;record.status='waiting';record.generation++;if(state.decisionKind!=='risk')state.judgmentStatus='waiting';state.generation++;render();toast('合成人工修订已保存，依赖重算等待中');};
 const nform=$('#notes-form');if(nform)nform.onsubmit=e=>{e.preventDefault();state.note=$('#note').value;toast('笔记保存在本次原型内存中');};
 const age=$('#template-age');if(age)age.onchange=e=>{state.templateAge=e.target.value;state.templatePreview=false;state.templatePublished=false;render();};
 const mode=$('#event-mode');if(mode)mode.onchange=e=>{state.eventMode=e.target.value;state.templatePreview=false;render();};
 const threshold=$('#strategy-threshold');if(threshold)threshold.onchange=e=>{state.strategyThreshold=e.target.value;state.strategyPreview=false;render();};
 const rform=$('#roles-form');if(rform)rform.onsubmit=e=>e.preventDefault();
}
document.addEventListener('click',e=>{
 const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;
 if(action.startsWith('open-evidence-')){if(currentRoute()[0]!=='evidence')state.evidenceReturn=location.hash.slice(1)||'news';}
 else if(action==='clear-news'){state.newsCompany='all';state.newsType='all';state.newsPeriod='all';render();}
 else if(action.startsWith('open-valuation-')){state.selectedSecurity=action.slice(15);state.tab='valuation';render();}
 else if(action==='show-scores'){state.tab='scores';render();}
 else if(action==='open-impact'){state.decisionKind='impact';state.editDecision=false;state.replacement=Number.isFinite(Number(state.decisionRecords.impact.value))?String(Number(state.decisionRecords.impact.value)):'';render();}
 else if(action.startsWith('watch-')){const id=action.slice(6);state.watch=state.watch.includes(id)?state.watch.filter(x=>x!==id):[...state.watch,id];render();toast('已更新这一只证券的自选');}
 else if(action.startsWith('tab-')){state.tab=action.slice(4);render();}
 else if(action.startsWith('market-')){state.market=action.slice(7);render();}
 else if(action.startsWith('decision-')){state.decisionKind=action.slice(9);state.editDecision=false;state.grade=/^[0-4]$/.test(state.decisionRecords.rubric.value)?state.decisionRecords.rubric.value:'';state.replacement=Number.isFinite(Number(state.decisionRecords.impact.value))?String(Number(state.decisionRecords.impact.value)):'';render();}
 else if(action.startsWith('valuation-')){state.selectedSecurity=action.slice(10);render();}
 else if(action.startsWith('unwatch-')){state.watch=state.watch.filter(x=>x!==action.slice(8));render();}

 else if(action==='risk-detail'||action==='rubric-detail'){state.decisionKind=action==='risk-detail'?'risk':'rubric';state.editDecision=false;state.grade=/^[0-4]$/.test(state.decisionRecords.rubric.value)?state.decisionRecords.rubric.value:'';navigate('decisions/'+state.company);}
 else if(action==='finish-load'){state.scenario='normal';state.market='all';state.changeType='all';render();}
 else if(action==='evidence-revoke'){dialog('<h2>原文现已不可访问</h2><p>权利已撤销或到期，保留引用与不可访问原因，不返回缓存正文。当前依赖评分需要重新检查覆盖度。</p><p class="footnote">此弹窗演示正式页面状态，不执行真实撤权。</p>');}
 else if(action==='show-recompute'){state.scenario='normal';dialog('<h2>合成重算结果对照</h2><p>新判断已记录为人工有效值。实际重算应返回同一快照的经营分、覆盖与A/H评估。</p><p>本原型没有Decimal评分或状态机，仅展示“判断已保存”与“计算已完成”两个阶段。</p>');}
 else if(action==='release-override'){if(!can('analysis.override'))return;state.decisionRecords[state.decisionKind].status='released';state.decisionRecords[state.decisionKind].value='无有效判断，待重评';if(state.decisionKind!=='risk')state.judgmentStatus='waiting';state.generation++;dialog('<h2>人工覆盖已解除（合成）</h2><p>当前等待新的有效判断；不恢复过期的系统判断。拒绝风险与解除覆盖是不同动作。</p>');render();}
 else if(action==='resolve-conflict'){state.scenario='normal';state.generation++;state.decisionRecords[state.decisionKind].generation++;render();toast('已载入新版本，你的新值和理由仍保留；可重试保存');}
 else if(action==='save-template'){if(!can('template.edit'))return;state.templateDraft=true;toast('合成模板草稿已保存，尚未发布');}
 else if(action==='preview-template'){if(!can('template.edit'))return;state.templatePreview=true;render();}
 else if(action==='restore-template'){state.templateAge='180';state.eventMode='enabled';state.templatePreview=false;render();}
 else if(action==='publish-template'){if(!can('template.publish')||!state.templatePreview)return;state.templatePublished=true;state.templatePreview=false;render();toast('演示新模板发布；旧策略版本继续固定旧口径');}
 else if(action==='simulate-strategy'){if(!can('strategy.publish'))return;state.strategyPreview=true;render();}
 else if(action==='publish-strategy'){if(!can('strategy.publish')||!state.strategyPreview)return;state.strategyPublished=true;state.strategyPreview=false;render();toast('演示发布2，变化分类CONFIG_CHANGE');}
 else if(action==='rollback-preview'){dialog('<h2>回滚提案预览</h2><p>引用发布1配置，创建新的版本3；原发布2与历史解释保留。受影响证券仍为002594、01211、000651。</p><p class="footnote">这里只查看设计提案，不执行发布。</p>');}
 else if(action==='toggle-source'){if(!can('source.manage'))return;state.sourcePaused=!state.sourcePaused;render();}
 else if(action==='import-fixture'){if(!can('source.manage'))return;state.imported=true;toast('合成导入结果演示已就绪，未运行采集');navigate('jobs');}
 else if(action==='source-preview'){dialog('<h2>配置发布预览</h2><p>范围为两家公司、三只证券；本地合成fixture，无网络请求和采购。正常接入时再明确回溯期、请求量、权利和恢复方法。</p>');}
 else if(action==='retry-preview'){if(!can('job.retry'))return;dialog('<h2>只恢复一个失败项</h2><p>对象：002594 / 2026-09-30最终行情。沿用固定cutoff和业务键，不重跑历史membership。</p><div class="actions">'+btn('确认合成恢复','confirm-retry','primary')+'</div>');}
 else if(action==='confirm-retry'){if(!can('job.retry'))return;state.jobRecovered=true;$('#dialog').close();render();toast('固定恢复结果已展示；未调用源或任务服务');}
 else if(action==='identity-preview'){dialog('<h2>主数据变更影响预览</h2><p>比亚迪关联两只证券、一个策略release及当前研究判断。身份修改需要固定旧/新映射、generation和证据；历史引用保留。</p><p class="footnote">本轮只展示范围，未提出真实合并对象。</p>');}
 else if(action==='correction-preview'){if(!can('quality.correct'))return;dialog('<h2>历史更正范围</h2><p>s2原输入错误；s4/s6仍有独立有效依据。窗口重放后当前IN保持，追加CORRECTION说明。</p><div class="actions">'+btn('追加合成更正说明','confirm-correction','primary')+'</div>');}
 else if(action==='confirm-correction'){if(!can('quality.correct'))return;state.correctionAdded=true;$('#dialog').close();render();}
 else if(action==='role-preview'){if(!can('role.assign'))return;const checked=[...document.querySelectorAll('input[name="roles"]:checked')].map(x=>x.value);dialog('<h2>合成成员的权限差异</h2><p>当前：研究员。</p><p>准备设为：'+esc(checked.join('、')||'无业务角色')+'。</p><p>只改变这一名成员，下一请求和后台提交按新能力检查。此示例不移除最后管理员。</p><div class="actions">'+btn('保存合成角色组合','confirm-role','primary')+'</div>');}
 else if(action==='confirm-role'){if(!can('role.assign'))return;state.roleChanges=true;$('#dialog').close();toast('角色组合仅作原型演示，未修改真实权限');}
});
$('#role').onchange=e=>{state.role=e.target.value;state.scenario='normal';if(state.role==='system_admin'){state.mode='admin';navigate('roles');}else if(state.role==='data_admin'){state.mode='admin';navigate('sources');}else{state.mode='business';render();}};
$('#business-mode').onclick=()=>{state.mode='business';navigate('changes');render();};
$('#admin-mode').onclick=()=>{state.mode='admin';navigate(can('source.manage')?'sources':can('role.assign')?'roles':can('analysis.override')?'decisions':can('template.edit')?'templates':'quality');render();};
$('#global-search').onkeydown=e=>{if(e.key==='Enter'){state.query=e.target.value;state.mode='business';navigate('companies');}};
$('#reset').onclick=()=>{state=initial();$('#global-search').value='';if($('#dialog').open)$('#dialog').close();navigate('changes');render();toast('已重置合成演示');};
$('#close-dialog').onclick=()=>$('#dialog').close();
window.matchMedia('(max-width:750px)').addEventListener('change',()=>render());
window.addEventListener('hashchange',()=>{render();$('#main').focus({preventScroll:true});window.scrollTo(0,0);});
render();
